#!/usr/bin/env node
// The shared registries, generated from their TypeScript modules.
//
// Each registry in docs/agents/areas/registries.md is one table in
// packages/contracts/src/<name>.ts. The fixture the tests pin and the table the
// Swift clients read are both written from that module, never typed:
//
//   packages/contracts/src/<name>.ts  ->  fixtures/<name>.json
//                                     ->  Sources/Generated/<Name>Registry.swift
//
//   pnpm registries:gen     # --write: rewrite every generated file
//   pnpm registries:check   # --check: exit 1 when a file on disk is stale (part of contracts:check)
//   pnpm registries:test    # the emitter helpers against small shapes
//
// Run through the TypeScript resolve hook, the way the work-ranker cases
// (packages/contracts/scripts/work-ranker-fixture.ts) are, because the modules import their siblings without an extension.
//
// The Swift file holds the table as data and nothing else. The types, the
// words, the symbols and the behaviour stay in the hand-written file, which
// reads the generated table (`extension SubjectStatusRegistry { static let ... }`).
// A registry is added by writing its entry in REGISTRIES below.
//
// A fixture is generated whole, or in part. Where it also holds hand-written
// cases (the inputs and answers a rule is held to), the entry's `fixture` gets
// the file as it is on disk and returns it with only the table keys replaced
// (`withKeys`), so the cases stay as written and the table can never be.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, relative, resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');

const SWIFT_KEYWORDS = new Set(['default', 'in', 'is', 'as', 'for', 'if', 'else', 'return', 'type', 'self', 'where', 'case', 'enum', 'struct', 'class', 'let', 'var', 'func', 'import', 'operator', 'protocol', 'static', 'true', 'false', 'nil', 'init', 'super', 'throws', 'internal', 'public', 'private', 'fileprivate', 'open', 'extension', 'subscript', 'typealias', 'associatedtype', 'deinit', 'inout', 'rethrows', 'guard', 'defer', 'do', 'repeat', 'while', 'switch', 'break', 'continue', 'fallthrough', 'throw', 'try', 'catch', 'Any', 'Self']);

/** A Swift string literal. Wire words are plain text; anything that needs a \u escape is a mistake to look at, not to paper over. */
export function swiftString(value) {
  const literal = JSON.stringify(value);
  if (/\\u/.test(literal)) throw new Error(`${literal}: not a plain string; add the escape to swiftString on purpose`);
  return literal;
}

/** An enum case or property name taken from a wire value (`project`, `startsCollapsed`). */
export function swiftName(value) {
  if (!/^[a-z][A-Za-z0-9]*$/.test(value)) throw new Error(`${value}: not usable as a Swift name`);
  if (SWIFT_KEYWORDS.has(value)) throw new Error(`${value}: is a Swift keyword`);
  return value;
}

/** `["a", "b"]`, wrapped one element a line once it would pass 100 columns. */
export function swiftStringArray(values, indent) {
  const items = values.map(swiftString);
  const flat = `[${items.join(', ')}]`;
  if (indent.length + flat.length < 100) return flat;
  return `[\n${items.map((item) => `${indent}    ${item},`).join('\n')}\n${indent}]`;
}

