const json = (value) => `${JSON.stringify(value, null, 2)}\n`;

/** `mark-seen` -> `markSeen`, `inbox_talk` -> `inboxTalk`: the Swift case a wire id is declared as. */
export function swiftCase(id) {
  const name = id.replace(/[-_]([a-z0-9])/g, (_, letter) => letter.toUpperCase());
  if (!/^[a-z][A-Za-z0-9]*$/.test(name)) throw new Error(`${id}: not usable as a Swift case`);
  // Only ever written after a dot (`.open`), where a keyword is fine, bar these.
  if (['init', 'self', 'Type', 'Protocol'].includes(name)) throw new Error(`${id}: ${name} is not a usable member name`);
  return name;
}

/** A localized word: the English source stays in the TypeScript module and reaches the string catalog from here. */
export const swiftLocalized = (value) => `String(localized: ${swiftString(value)})`;

/** `.inProgress = "in_progress"` when the Swift case differs from the wire value. */
const swiftCaseDeclaration = (id) => {
  const name = swiftCase(id);
  const declared = SWIFT_KEYWORDS.has(name) ? `\`${name}\`` : name;
  return name === id ? `    case ${declared}` : `    case ${declared} = ${swiftString(id)}`;
};

/**
 * A wire enum and the word each case shows, as Swift: the enum's cases in the
 * module's order, then an extension with a `switch` per word property. The
 * hand-written file extends the enum with behaviour only.
 *
 *   swiftWordEnum({ name: 'CrmTaskStatus', ids, words: { menuTitle: labels } })
 */
export function swiftWordEnum({ name, doc = [], ids, words, conformances = 'String, Codable, CaseIterable, Sendable', extendOnly = false, caseNames = {}, open = false, fallback = null }) {
  // `extendOnly`: the enum stays hand-written (its cases carry their own docs);
  // only the words are generated, and the `switch` fails to compile when a case
  // is missing. `caseNames` names a case the Swift enum spells differently.
  // `open`: a generated RawRepresentable struct, so the switch needs a default.
  // `fallback`: a Swift expression for every case a table leaves out.
  const caseOf = (id) => caseNames[id] ?? swiftCase(id);
  const lines = extendOnly ? [] : [...doc.map((line) => `/// ${line}`), `enum ${name}: ${conformances} {`, ...ids.map(swiftCaseDeclaration), '}', ''];
  const properties = Object.entries(words);
  if (properties.length === 0) return lines.join('\n');
  lines.push(`extension ${name} {`);
  properties.forEach(([property, table], index) => {
    if (index > 0) lines.push('');
    lines.push(`    var ${swiftName(property)}: String {`, '        switch self {');
    for (const id of ids) {
      if (typeof table[id] !== 'string') {
        if (fallback !== null) continue;
        throw new Error(`${name}.${property}: no word for ${id}`);
      }
      lines.push(`        case .${caseOf(id)}: ${swiftLocalized(table[id])}`);
    }
    if (fallback !== null) lines.push(`        default: ${fallback}`);
    else if (open) lines.push('        default: rawValue');
    lines.push('        }', '    }');
  });
  lines.push('}', '');
  return lines.join('\n');
}

/**
 * A fixture that keeps what is hand-written in it. `existing` is the file as it
 * is on disk, `generated` the keys the table owns. Existing keys keep their place
 * and their value unless generated; a new generated key goes after the generated
 * key before it (or first, after `version`).
 */
export function withKeys(existing, generated) {
  const keys = Object.keys(existing);
  let previous = keys.includes('version') ? 'version' : null;
  for (const key of Object.keys(generated)) {
    if (!keys.includes(key)) keys.splice(previous === null ? 0 : keys.indexOf(previous) + 1, 0, key);
    previous = key;
  }
  return Object.fromEntries(keys.map((key) => [key, key in generated ? generated[key] : existing[key]]));
}

/**
 * JSON for a fixture people also read: objects and arrays that hold only plain
 * values sit on one line when they fit, everything else opens up.
 */
export function compactJson(value, indent = '') {
  const leaf = (item) => item === null || typeof item !== 'object';
  const inline = (item) => (Array.isArray(item) ? item.every(leaf) : Object.values(item).every(leaf));
  if (leaf(value)) return JSON.stringify(value);
  const empty = Array.isArray(value) ? value.length === 0 : Object.keys(value).length === 0;
  if (empty) return Array.isArray(value) ? '[]' : '{}';
  if (inline(value)) {
    const one = Array.isArray(value)
      ? `[${value.map((item) => JSON.stringify(item)).join(', ')}]`
      : `{ ${Object.entries(value).map(([key, item]) => `${JSON.stringify(key)}: ${JSON.stringify(item)}`).join(', ')} }`;
    if (indent.length + one.length < 180) return one;
  }
  const inner = `${indent}  `;
  if (Array.isArray(value)) return `[\n${value.map((item) => `${inner}${compactJson(item, inner)}`).join(',\n')}\n${indent}]`;
  return `{\n${Object.entries(value).map(([key, item]) => `${inner}${JSON.stringify(key)}: ${compactJson(item, inner)}`).join(',\n')}\n${indent}}`;
}

